B.aLI=new A.aQ("wrap-pollo","Wrap de pollo con queso, ma\xedz y pepino",15,"1 raci\xf3n",B.ads,B.aps,"Envuelto en papel de aluminio sirve para llevar.",530,35,B.V,B.eT,!1)
B.afq=s(["200 g de arroz","200 g de pollo troceado","100 g de lomo o costilla de cerdo","100 g de jud\xedas verdes","2 cucharadas de tomate frito","800 ml de agua o caldo","Aceite, sal, piment\xf3n","Colorante o azafr\xe1n"],t.s)
B.afJ=s(["Dora la carne en la paellera con aceite y sal, 8 minutos.","A\xf1ade las jud\xedas y rehoga 3 minutos.","A\xf1ade el tomate y el piment\xf3n y remueve 1 minuto.","Echa el agua caliente y el colorante y deja que hierva.","Reparte el arroz: 10 minutos a fuego fuerte y 8 a fuego suave, sin remover.","Deja reposar 5 minutos tapada con un trapo."],t.s)
B.aM1=new A.aQ("paella",u.h,45,"2 raciones",B.afq,B.afJ,"La segunda raci\xf3n, a un t\xe1per para otro d\xeda o al congelador.",740,37,B.V,B.cf,!1)
